【题 8.26】请读程序：
上面程序的运行结果是______。

```c
#include <stdio.h>
#define LETTER 0
int main()
{ char str[20]="C Language",c;
  int i;
  i=0;
  while((c=str[i])!='\0')
    { i++;
      #if LETTER
        if (c>='a'&&c<='z')
          c=c-32;
      #else
        if (c>='A'&&c<='Z')
          c=c+32;
      #endif
      printf("%c",c);
    }
  return 0;
}
```

